#!/usr/bin/env python3
"""Generate the 20 local, self-contained website templates distributed with the project."""
from html import escape
from pathlib import Path

SITES = [
    ("north", "North Studio", "Пространство для хороших идей", "Дизайн, который помогает сосредоточиться на главном.", "Стратегия", "Интерфейсы", "Визуальные системы", "#e9eee9", "#1e2922", "#6b8272"),
    ("atelier", "Atelier Form", "Форма следует за смыслом", "Небольшая коллекция идей о визуальной культуре и предметах.", "Подход", "Материалы", "Вдохновение", "#f4eee7", "#2d261f", "#9c6e54"),
    ("still", "Still Journal", "Заметки о простых вещах", "Тихое место для наблюдений, находок и коротких историй.", "Истории", "Наблюдения", "Подборки", "#f5f2eb", "#272722", "#a0634b"),
    ("moss", "Moss & Light", "Ближе к природе", "Идеи для спокойного дома и вдумчивой повседневности.", "Растения", "Дом", "Время для себя", "#e8efe4", "#223525", "#668761"),
    ("orbit", "Orbit Notes", "Идеи на орбите", "Коротко о технологиях, творчестве и вещах, которые нас вдохновляют.", "Технологии", "Культура", "Идеи", "#101522", "#f0f3ff", "#9baee9"),
    ("mono", "Mono Works", "Меньше деталей. Больше ясности.", "Пространство для проектов, в которых каждая деталь на своём месте.", "Направление", "Процессы", "Результаты", "#151515", "#f3f3ef", "#c3c7bd"),
    ("field", "Field Notes", "Мир начинается с наблюдения", "Небольшой журнал о местах, маршрутах и повседневных открытиях.", "Маршруты", "Места", "Заметки", "#f0ecdd", "#32352a", "#a1844e"),
    ("tide", "Tide & Co.", "На своей волне", "Собираем мысли о работе, отдыхе и балансе между ними.", "Ритм", "Идеи", "Вдохновение", "#e4f0ef", "#17383d", "#5a9593"),
    ("pulse", "Pulse Lab", "Движение начинается с идеи", "Место для экспериментов и новых цифровых форматов.", "Исследования", "Концепции", "Практика", "#171322", "#f3eeff", "#b9a1eb"),
    ("common", "Common Ground", "Идеи, которыми хочется делиться", "Размышления о культуре, сообществе и совместном творчестве.", "Люди", "Культура", "Проекты", "#f2e9de", "#392820", "#c16e52"),
    ("luma", "Luma Space", "Светлые идеи каждый день", "Вдохновение для проектов, интерьеров и повседневных решений.", "Идеи", "Пространства", "Детали", "#f9f4e8", "#302d26", "#c59f5b"),
    ("frame", "Frame Journal", "Истории в деталях", "Визуальные заметки о композиции, форме и окружающем мире.", "Кадры", "Эссе", "Авторы", "#e8e9ed", "#222631", "#737f9f"),
    ("paper", "Paper & Pixel", "От заметки к идее", "Наблюдения о создании цифровых продуктов и понятных интерфейсов.", "Продукт", "Дизайн", "Методы", "#f5f3ee", "#282b2e", "#708a8a"),
    ("terra", "Terra Notes", "Вещи с чувством места", "Неспешный журнал о природных материалах и окружающем пространстве.", "Материалы", "Места", "Наблюдения", "#eee6da", "#3d2f27", "#b47654"),
    ("wave", "Wave Studio", "Пусть идеи находят форму", "Новые подходы к созданию простых и выразительных решений.", "Исследовать", "Создавать", "Делиться", "#e6ebf4", "#202c44", "#6d89c4"),
    ("daylight", "Daylight", "Хороший день начинается здесь", "Лаконичные идеи для работы, отдыха и привычных дел.", "Утро", "Фокус", "Вечер", "#f9f0df", "#423326", "#ce9863"),
    ("outline", "Outline", "Важное становится заметнее", "О дизайне, ясных решениях и красоте продуманных деталей.", "Идея", "Процесс", "Форма", "#eeeef0", "#26262b", "#777c8b"),
    ("bloom", "Bloom Journal", "Пространство для роста", "Небольшие идеи, которые помогают двигаться вперёд.", "Развитие", "Практика", "Вдохновение", "#f5ebe9", "#3c292b", "#c48c98"),
    ("atlas", "Atlas Club", "Мир полон интересного", "Маршруты, идеи и впечатления для любопытных.", "Направления", "Истории", "Открытия", "#e9eee9", "#1f302c", "#5a887b"),
    ("slow", "Slow Office", "Работа в своём ритме", "Простые инструменты и мысли для более спокойного рабочего дня.", "Фокус", "Привычки", "Перерывы", "#f4f0e9", "#312f29", "#a79675"),
]

ROOT = Path(__file__).resolve().parents[1] / "templates"
for number, (slug, name, title, description, one, two, three, bg, fg, accent) in enumerate(SITES, 1):
    slug, name, title, description, one, two, three = map(escape, (slug, name, title, description, one, two, three))
    layout = number % 4
    page = f'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="{description}"><title>{name} — {title}</title><link rel="icon" href="/favicon.svg" type="image/svg+xml">
<style>
:root{{--bg:{bg};--ink:{fg};--accent:{accent}}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}a{{color:inherit;text-decoration:none}}a:focus-visible{{outline:2px solid var(--accent);outline-offset:5px}}.wrap{{width:min(1120px,calc(100% - 48px));margin:auto}}header{{display:flex;justify-content:space-between;align-items:center;padding:28px 0;border-bottom:1px solid color-mix(in srgb,var(--ink) 18%,transparent)}}.logo{{font-weight:760;font-size:1.15rem;letter-spacing:-.04em}}.logo:before{{content:"";display:inline-block;width:13px;height:13px;background:var(--accent);margin-right:10px;transform:rotate(45deg);border-radius:3px}}nav{{display:flex;gap:28px;font-size:.87rem}}.hero{{min-height:68vh;display:grid;grid-template-columns:1.2fr .8fr;gap:5vw;align-items:center;padding:70px 0}}.eyebrow{{text-transform:uppercase;letter-spacing:.18em;font-size:.68rem;font-weight:700;color:var(--accent)}}h1{{font-size:clamp(3rem,7vw,6.5rem);line-height:1.02;letter-spacing:-.065em;font-weight:650;margin:20px 0 26px;max-width:13ch}}.lead{{font-size:clamp(1.05rem,1.5vw,1.3rem);max-width:40ch;opacity:.74}}.action{{display:inline-flex;margin-top:24px;padding:13px 20px;border:1px solid var(--ink);border-radius:40px;font-size:.9rem;transition:background .2s,color .2s}}.action:hover{{background:var(--ink);color:var(--bg)}}.art{{aspect-ratio:1;position:relative;display:grid;place-items:center}}.art:before{{content:"";width:78%;height:78%;border-radius:{'50%' if layout in (0, 3) else '26% 60% 28% 58%'};background:linear-gradient(135deg,var(--accent),transparent);opacity:.6;transform:rotate(-18deg)}}.art:after{{content:"";position:absolute;width:56%;height:56%;border:1px solid var(--ink);border-radius:50%;opacity:.32;transform:translate(12%,-9%)}}.line{{display:flex;justify-content:space-between;border-top:1px solid color-mix(in srgb,var(--ink) 18%,transparent);padding-top:25px;font-size:.75rem;opacity:.7}}section.cards{{padding:80px 0 110px}}h2{{font-size:clamp(2rem,4vw,3.5rem);letter-spacing:-.05em;line-height:1.1}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}}article{{border-top:1px solid var(--ink);padding:22px 12px 22px 0}}article small{{color:var(--accent)}}article h3{{font-size:1.25rem;letter-spacing:-.03em}}article p{{opacity:.7;max-width:34ch}}footer{{border-top:1px solid color-mix(in srgb,var(--ink) 18%,transparent);padding:28px 0 35px;font-size:.8rem;opacity:.72;display:flex;justify-content:space-between}}.variant-1 .hero{{grid-template-columns:.9fr 1.1fr}}.variant-1 .art{{order:-1}}.variant-2 .hero{{grid-template-columns:1fr 1fr}}.variant-2 .art:before{{border-radius:8%}}.variant-3 .hero{{text-align:center;display:flex;flex-direction:column;justify-content:center}}.variant-3 h1,.variant-3 .lead{{margin-left:auto;margin-right:auto}}.variant-3 .art{{width:180px;position:absolute;right:6%;opacity:.35;z-index:-1}}@media(max-width:700px){{nav{{gap:14px}}.wrap{{width:calc(100% - 36px)}}.hero,.variant-1 .hero,.variant-2 .hero{{grid-template-columns:1fr;min-height:auto;padding:70px 0 45px}}.art{{max-width:270px;width:75%;margin:auto}}.variant-1 .art{{order:0}}.grid{{grid-template-columns:1fr}}section.cards{{padding:50px 0 70px}}}}@media(prefers-reduced-motion:reduce){{html{{scroll-behavior:auto}}*{{transition:none!important}}}}
</style></head><body class="variant-{layout}"><header class="wrap"><a class="logo" href="/">{name}</a><nav aria-label="Навигация"><a href="#about">О проекте</a><a href="#ideas">Направления</a></nav></header>
<main class="wrap"><section class="hero" id="about"><div><span class="eyebrow">Небольшой проект · большая идея</span><h1>{title}</h1><p class="lead">{description}</p><a class="action" href="#ideas">Узнать больше &nbsp; ↗</a></div><div class="art" aria-hidden="true"></div></section><div class="line"><span>ПРОСТРАНСТВО ДЛЯ ИДЕЙ</span><span>01 / 03</span></div><section class="cards" id="ideas"><span class="eyebrow">Наши направления</span><h2>То, что нас вдохновляет.</h2><div class="grid"><article><small>01 /</small><h3>{one}</h3><p>Изучаем интересные детали и собираем то, что помогает увидеть привычные вещи по-новому.</p></article><article><small>02 /</small><h3>{two}</h3><p>Ищем понятные решения и оставляем пространство для экспериментов.</p></article><article><small>03 /</small><h3>{three}</h3><p>Делимся идеями и вдохновением, которые можно применить каждый день.</p></article></div></section></main><footer class="wrap"><span>© {name}</span><span>Сделано с вниманием к деталям.</span></footer></body></html>'''
    path = ROOT / f"{number:02d}-{slug}" / "index.html"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(page, encoding="utf-8")
    error_page = f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Страница не найдена — {name}</title><link rel="icon" href="/favicon.svg" type="image/svg+xml"><style>body{{margin:0;background:{bg};color:{fg};font:16px/1.6 system-ui,sans-serif}}main{{max-width:50rem;margin:15vh auto;padding:24px}}small{{color:{accent};letter-spacing:.16em}}h1{{font-size:clamp(3rem,7vw,6rem);line-height:1.05;letter-spacing:-.06em}}a{{color:inherit;text-underline-offset:5px}}</style></head><body><main><small>{name} / 404</small><h1>Страница не найдена.</h1><p>Возможно, адрес изменился. Вернитесь на главную страницу.</p><a href="/">На главную ↗</a></main></body></html>'''
    (path.parent / '404.html').write_text(error_page, encoding='utf-8')
    initials = ''.join(word[0] for word in name.split()[:2] if word[0].isalpha()).upper()
    favicon = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="{accent}"/><text x="32" y="41" text-anchor="middle" font-family="sans-serif" font-weight="700" font-size="25" fill="{bg}">{initials}</text></svg>'
    (path.parent / 'favicon.svg').write_text(favicon, encoding='utf-8')
cards = []
for number, (slug, name, title, *_rest) in enumerate(SITES, 1):
    href = f'templates/{number:02d}-{slug}/index.html'
    cards.append(f'<a class="card" href="{href}"><div class="preview"><iframe src="{href}" title="{escape(name)}" loading="lazy" tabindex="-1"></iframe></div><div class="meta"><span>{number:02d} / {escape(name)}</span><span>Открыть ↗</span></div><p>{escape(title)}</p></a>')
overview = '''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>20 шаблонов сайта</title><style>body{margin:0;background:#0b0d10;color:#f1f2f3;font:16px/1.5 system-ui,sans-serif}main{width:min(1280px,calc(100% - 48px));margin:60px auto}small{color:#a9b5bb;letter-spacing:.18em;text-transform:uppercase}h1{font-size:clamp(2.8rem,6vw,5.5rem);line-height:1;letter-spacing:-.06em;margin:20px 0}p{color:#a9b5bb}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px;margin-top:50px}.card{color:inherit;text-decoration:none;background:#171b20;border:1px solid #2b3037;border-radius:14px;overflow:hidden}.card:hover{border-color:#9ca9ad}.preview{height:220px;overflow:hidden;background:#eee}.preview iframe{width:1100px;height:780px;transform:scale(.32);transform-origin:top left;border:0;pointer-events:none}.meta{display:flex;justify-content:space-between;padding:18px 18px 0;font-size:.85rem;font-weight:650}.card p{padding:0 18px 18px;margin:6px 0 0;font-size:.85rem}</style></head><body><main><small>Selfsteal installer / шаблоны</small><h1>20 идей для сайта.</h1><p>Откройте карточку, чтобы посмотреть шаблон целиком.</p><div class="grid">''' + ''.join(cards) + '</div></main></body></html>'
(ROOT.parent / 'preview.html').write_text(overview, encoding='utf-8')
print(f"Generated {len(SITES)} templates in {ROOT}")
